import UIKit
import SafariServices
import MenuItemKit
import WebKit

/// Protocol which is used from `FolioReaderPage`s.
@objc public protocol FolioReaderPageDelegate: class {

    /**
     Notify that the page will be loaded. Note: The webview content itself is already loaded at this moment. But some java script operations like the adding of class based on click listeners will happen right after this method. If you want to perform custom java script before this happens this method is the right choice. If you want to modify the html content (and not run java script) you have to use `htmlContentForPage()` from the `FolioReaderCenterDelegate`.

     - parameter page: The loaded page
     */
    @objc optional func pageWillLoad(_ page: FolioReaderPage)

    /**
     Notifies that page did load. A page load doesn't mean that this page is displayed right away, use `pageDidAppear` to get informed about the appearance of a page.

     - parameter page: The loaded page
     */
    @objc optional func pageDidLoad(_ page: FolioReaderPage)

    /**
     Notifies that page receive tap gesture.

     - parameter recognizer: The tap recognizer
     */
    @objc optional func pageTap(_ recognizer: UITapGestureRecognizer)
}

open class FolioReaderPage: UICollectionViewCell, WKNavigationDelegate, UIGestureRecognizerDelegate {
    weak var delegate: FolioReaderPageDelegate?
    var readerContainer: FolioReaderContainer?

    /// The index of the current page. Note: The index start at 1!
    open var pageNumber: Int!
    open var webView: FolioReaderWebView?

    fileprivate var colorView: UIView!
    fileprivate var shouldShowBar = true
    fileprivate var menuIsVisible = false

    fileprivate var readerConfig: FolioReaderConfig {
        guard let readerContainer = readerContainer else { return FolioReaderConfig() }
        return readerContainer.readerConfig
    }

    fileprivate var book: FRBook {
        guard let readerContainer = readerContainer else { return FRBook() }
        return readerContainer.book
    }

    fileprivate var folioReader: FolioReader {
        guard let readerContainer = readerContainer else { return FolioReader() }
        return readerContainer.folioReader
    }

    // MARK: - View life cicle

    public override init(frame: CGRect) {
        // Init explicit attributes with a default value. The `setup` function MUST be called to configure the current object with valid attributes.
        self.readerContainer = FolioReaderContainer(withConfig: FolioReaderConfig(), folioReader: FolioReader(), epubPath: "")
        super.init(frame: frame)
        self.backgroundColor = UIColor.clear

        NotificationCenter.default.addObserver(self, selector: #selector(refreshPageMode), name: NSNotification.Name(rawValue: "needRefreshPageMode"), object: nil)
    }

    public func setup(withReaderContainer readerContainer: FolioReaderContainer) {
        self.readerContainer = readerContainer
        guard let readerContainer = self.readerContainer else { return }

        if webView == nil {
            webView = FolioReaderWebView(frame: webViewFrame(), readerContainer: readerContainer)
            webView?.autoresizingMask = [.flexibleWidth, .flexibleHeight]
            // Don't disable scroll indicators here - let setupScrollDirection handle this
            webView?.backgroundColor = .clear
            self.contentView.addSubview(webView!)
        }
        webView?.navigationDelegate = self

        if colorView == nil {
            colorView = UIView()
            colorView.backgroundColor = self.readerConfig.nightModeBackground
            webView?.scrollView.addSubview(colorView)
        }

        // Remove all gestures before adding new one
        webView?.gestureRecognizers?.forEach({ gesture in
            webView?.removeGestureRecognizer(gesture)
        })
        let tapGestureRecognizer = UITapGestureRecognizer(target: self, action: #selector(handleTapGesture(_:)))
        tapGestureRecognizer.numberOfTapsRequired = 1
        tapGestureRecognizer.delegate = self
        webView?.addGestureRecognizer(tapGestureRecognizer)
    }

    required public init?(coder aDecoder: NSCoder) {
        fatalError("storyboards are incompatible with truth and beauty")
    }

    deinit {
        webView?.scrollView.delegate = nil
        webView?.navigationDelegate = nil
        NotificationCenter.default.removeObserver(self)
    }

    override open func layoutSubviews() {
        super.layoutSubviews()

        webView?.frame = webViewFrame()
    }

    func webViewFrame() -> CGRect {
        guard (self.readerConfig.hideBars == false) else {
            return bounds
        }

        let statusbarHeight = UIApplication.shared.statusBarFrame.size.height
        let navBarHeight = self.folioReader.readerCenter?.navigationController?.navigationBar.frame.size.height ?? CGFloat(0)
        let navTotal = self.readerConfig.shouldHideNavigationOnTap ? 0 : statusbarHeight + navBarHeight
        let paddingTop: CGFloat = 20
        let paddingBottom: CGFloat = 30

        return CGRect(
            x: bounds.origin.x,
            y: self.readerConfig.isDirection(bounds.origin.y + navTotal, bounds.origin.y + navTotal + paddingTop, bounds.origin.y + navTotal),
            width: bounds.width,
            height: self.readerConfig.isDirection(bounds.height - navTotal, bounds.height - navTotal - paddingTop - paddingBottom, bounds.height - navTotal)
        )
    }

    func loadHTMLString(_ htmlContent: String!, baseURL: URL!) {
        // Insert the stored highlights to the HTML
        let tempHtmlContent = htmlContentWithInsertHighlights(htmlContent)
        // Load the html into the webview
        webView?.alpha = 0

        // Real Device Fix: Use proper loading method for local files
        if #available(iOS 9.0, *) {
            // Write HTML to temp file and use loadFileURL for proper file access on real devices
            loadHTMLContentWithFileAccess(tempHtmlContent, baseURL: baseURL)
        } else {
            // Fallback for older iOS versions
            webView?.loadHTMLString(tempHtmlContent, baseURL: baseURL)
        }
    }

    /// Load HTML content with proper file access permissions for real devices
    @available(iOS 9.0, *)
    private func loadHTMLContentWithFileAccess(_ htmlContent: String, baseURL: URL) {
        do {
            // Real Device Fix: Preprocess HTML to fix image paths
            let processedHTML = normalizeResourcePaths(in: htmlContent, baseURL: baseURL)

            // Create a temporary HTML file in the EPUB directory for proper file access
            let tempDirectory = baseURL
            let tempFileName = "temp_\(UUID().uuidString).html"
            let tempFileURL = tempDirectory.appendingPathComponent(tempFileName)

            // Write HTML content to temporary file
            try processedHTML.write(to: tempFileURL, atomically: true, encoding: .utf8)

            // Load the file with read access to its directory
            // This grants WKWebView access to all resources in the EPUB directory
            webView?.loadFileURL(tempFileURL, allowingReadAccessTo: tempDirectory)

            // Schedule cleanup after a delay to allow loading
            DispatchQueue.main.asyncAfter(deadline: .now() + 2.0) {
                try? FileManager.default.removeItem(at: tempFileURL)
            }
        } catch {
            print("Failed to create temp HTML file, falling back to loadHTMLString: \(error)")
            // Fallback to original method if temp file creation fails
            webView?.loadHTMLString(htmlContent, baseURL: baseURL)
        }
    }

    /// Normalizes resource paths in HTML for proper loading on real devices
    private func normalizeResourcePaths(in html: String, baseURL: URL) -> String {
        var processedHTML = html

        // Real Device Fix: Ensure all image sources use proper relative paths
        // Handle case-sensitivity issues on real devices vs simulator

        // Fix common path issues:
        // 1. Remove leading slashes from relative paths
        // 2. Normalize ../ paths
        // 3. Ensure proper URL encoding

        // Pattern to find img tags with src attributes
        let imgPattern = "<img[^>]+src\\s*=\\s*['\"]([^'\"]+)['\"][^>]*>"
        if let regex = try? NSRegularExpression(pattern: imgPattern, options: [.caseInsensitive]) {
            let range = NSRange(processedHTML.startIndex..., in: processedHTML)
            let matches = regex.matches(in: processedHTML, range: range)

            // Process matches in reverse to maintain string indices
            for match in matches.reversed() {
                if match.numberOfRanges >= 2 {
                    let srcRange = match.range(at: 1)
                    if let swiftRange = Range(srcRange, in: processedHTML) {
                        let originalSrc = String(processedHTML[swiftRange])

                        // Skip absolute URLs and data URIs
                        if !originalSrc.hasPrefix("http") && !originalSrc.hasPrefix("data:") && !originalSrc.hasPrefix("file:") {
                            // Real Device Fix: Normalize the path
                            var normalizedSrc = originalSrc

                            // Remove leading slashes for relative paths
                            while normalizedSrc.hasPrefix("/") {
                                normalizedSrc.removeFirst()
                            }

                            // Only replace if we made changes
                            if normalizedSrc != originalSrc {
                                processedHTML = processedHTML.replacingOccurrences(
                                    of: "src=\"\(originalSrc)\"",
                                    with: "src=\"\(normalizedSrc)\""
                                )
                                processedHTML = processedHTML.replacingOccurrences(
                                    of: "src='\(originalSrc)'",
                                    with: "src='\(normalizedSrc)'"
                                )
                            }
                        }
                    }
                }
            }
        }

        return processedHTML
    }

    // MARK: - Highlights

    fileprivate func htmlContentWithInsertHighlights(_ htmlContent: String) -> String {
        var tempHtmlContent = htmlContent as NSString
        // Restore highlights
        guard let bookId = (self.book.name as NSString?)?.deletingPathExtension else {
            return tempHtmlContent as String
        }

        let highlights = Highlight.allByBookId(withConfiguration: self.readerConfig, bookId: bookId, andPage: pageNumber as NSNumber?)

        if (highlights.count > 0) {
            for item in highlights {
                let style = HighlightStyle.classForStyle(item.type)

                var tag = ""
                if let _ = item.noteForHighlight {
                    tag = "<highlight id=\"\(item.highlightId!)\" onclick=\"callHighlightWithNoteURL(this);\" class=\"\(style)\">\(item.content!)</highlight>"
                } else {
                    tag = "<highlight id=\"\(item.highlightId!)\" onclick=\"callHighlightURL(this);\" class=\"\(style)\">\(item.content!)</highlight>"
                }

                var locator = item.contentPre + item.content
                locator += item.contentPost
                locator = Highlight.removeSentenceSpam(locator) /// Fix for Highlights

                let range: NSRange = tempHtmlContent.range(of: locator, options: .literal)

                if range.location != NSNotFound {
                    let newRange = NSRange(location: range.location + item.contentPre.count, length: item.content.count)
                    tempHtmlContent = tempHtmlContent.replacingCharacters(in: newRange, with: tag) as NSString
                } else {
                    print("highlight range not found")
                }
            }
        }
        return tempHtmlContent as String
    }

    // MARK: - WKNavigationDelegate

    public func webView(_ webView: WKWebView, didCommit navigation: WKNavigation!) {
        guard let webView = webView as? FolioReaderWebView else {
            return
        }

        delegate?.pageWillLoad?(self)

        // Add the custom class based onClick listener
        self.setupClassBasedOnClickListeners()

        refreshPageMode()

        if self.readerConfig.enableTTS && !self.book.hasAudio {
            webView.js("wrappingSentencesWithinPTags()") { _ in }

            if let audioPlayer = self.folioReader.readerAudioPlayer, (audioPlayer.isPlaying() == true) {
                audioPlayer.readCurrentSentence()
            }
        }

        let direction: ScrollDirection = self.folioReader.needsRTLChange ? .positive(withConfiguration: self.readerConfig) : .negative(withConfiguration: self.readerConfig)

        if (self.folioReader.readerCenter?.pageScrollDirection == direction &&
            self.folioReader.readerCenter?.isScrolling == true &&
            self.readerConfig.scrollDirection != .horizontalWithVerticalContent) {
            scrollPageToBottom()
        }

        UIView.animate(withDuration: 0.2, animations: {webView.alpha = 1}, completion: { finished in
            webView.isColors = false
            self.webView?.createMenu(options: false)
        })
    }

    open func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
        guard let webView = webView as? FolioReaderWebView else { return }

        // Setup scroll direction after content is fully loaded
        delay(0.1) {
            webView.setupScrollDirection()
            self.delegate?.pageDidLoad?(self)
        }
    }

    open func webView(_ webView: WKWebView, decidePolicyFor navigationAction: WKNavigationAction, decisionHandler: @escaping (WKNavigationActionPolicy) -> Void) {

        let request = navigationAction.request
        guard
            let webView = webView as? FolioReaderWebView,
            let scheme = request.url?.scheme else {
                decisionHandler(WKNavigationActionPolicy.allow)
                return
        }

        guard let url = request.url
            else {
                decisionHandler(WKNavigationActionPolicy.cancel)
                return
        }

        if scheme == "highlight" || scheme == "highlight-with-note" {
            shouldShowBar = false

            guard let decoded = url.absoluteString.removingPercentEncoding
                else {
                    decisionHandler(WKNavigationActionPolicy.cancel)
                    return
            }
            let index = decoded.index(decoded.startIndex, offsetBy: 12)
            let rect = NSCoder.cgRect(for: String(decoded[index...]))

            webView.createMenu(options: true)
            webView.setMenuVisible(true, andRect: rect)
            menuIsVisible = true
            decisionHandler(WKNavigationActionPolicy.cancel)
            return
        } else if scheme == "play-audio" {
            guard let decoded = url.absoluteString.removingPercentEncoding
                else {
                    decisionHandler(WKNavigationActionPolicy.cancel)
                    return
            }
            let index = decoded.index(decoded.startIndex, offsetBy: 13)
            let playID = String(decoded[index...])
            let chapter = self.folioReader.readerCenter?.getCurrentChapter()
            let href = chapter?.href ?? ""
            self.folioReader.readerAudioPlayer?.playAudio(href, fragmentID: playID)

            decisionHandler(WKNavigationActionPolicy.cancel)
            return
        } else if scheme == "file" {

            let anchorFromURL = url.fragment

            // Handle internal url
            if !url.pathExtension.isEmpty {
                let pathComponent = (self.book.opfResource.href as NSString?)?.deletingLastPathComponent
                guard let base = ((pathComponent == nil || pathComponent?.isEmpty == true) ? self.book.name : pathComponent) else {
                    decisionHandler(WKNavigationActionPolicy.allow)
                    return
                }

                let path = url.path
                let splitedPath = path.components(separatedBy: base)

                // Return to avoid crash
                if (splitedPath.count <= 1 || splitedPath[1].isEmpty) {
                    decisionHandler(WKNavigationActionPolicy.allow)
                    return
                }

                let href = splitedPath[1].trimmingCharacters(in: CharacterSet(charactersIn: "/"))
                let hrefPage = (self.folioReader.readerCenter?.findPageByHref(href) ?? 0) + 1

                if (hrefPage == pageNumber) {
                    // Handle internal #anchor
                    if anchorFromURL != nil {
                        handleAnchor(anchorFromURL!, avoidBeginningAnchors: false, animated: true)
                        decisionHandler(WKNavigationActionPolicy.cancel)
                        return
                    }
                } else {
                    self.folioReader.readerCenter?.changePageWith(href: href, animated: true)
                }
               decisionHandler(WKNavigationActionPolicy.cancel)
                return
            }

            // Handle internal #anchor
            if anchorFromURL != nil {
                handleAnchor(anchorFromURL!, avoidBeginningAnchors: false, animated: true)
                decisionHandler(WKNavigationActionPolicy.cancel)
                return
            }

            decisionHandler(WKNavigationActionPolicy.allow)
            return

        } else if scheme == "mailto" {
            print("Email")
            decisionHandler(WKNavigationActionPolicy.allow)
            return
        } else if url.absoluteString != "about:blank" && scheme.contains("http") && navigationAction.navigationType == .linkActivated {
            let safariVC = SFSafariViewController(url: request.url!)
            safariVC.view.tintColor = self.readerConfig.tintColor
            self.folioReader.readerCenter?.present(safariVC, animated: true, completion: nil)
            decisionHandler(WKNavigationActionPolicy.cancel)
            return
        } else {
            // Check if the url is a custom class based onClick listerner
            var isClassBasedOnClickListenerScheme = false
            for listener in self.readerConfig.classBasedOnClickListeners {

                if scheme == listener.schemeName,
                    let absoluteURLString = request.url?.absoluteString,
                    let range = absoluteURLString.range(of: "/clientX=") {
                    let baseURL = String(absoluteURLString[..<range.lowerBound])
                    let positionString = String(absoluteURLString[range.lowerBound...])
                    if let point = getEventTouchPoint(fromPositionParameterString: positionString) {
                        let attributeContentString = (baseURL.replacingOccurrences(of: "\(scheme)://", with: "").removingPercentEncoding)
                        // Call the on click action block
                        listener.onClickAction(attributeContentString, point)
                        // Mark the scheme as class based click listener scheme
                        isClassBasedOnClickListenerScheme = true
                    }
                }
            }

            if isClassBasedOnClickListenerScheme == false {
                // Security: Validate URL before opening
                if validateExternalURL(url) {
                    // Use modern API instead of deprecated openURL
                    if #available(iOS 10.0, *) {
                        UIApplication.shared.open(url, options: [:]) { success in
                            if !success {
                                print("Failed to open URL: \(url)")
                            }
                        }
                    } else {
                        UIApplication.shared.openURL(url)
                    }
                    decisionHandler(WKNavigationActionPolicy.cancel)
                    return
                }
            } else {
                decisionHandler(WKNavigationActionPolicy.cancel)
                return
            }
        }

        decisionHandler(WKNavigationActionPolicy.allow)

    }

    // MARK: - Security Methods (Section 3)

    /// Validates external URLs before opening with security checks
    private func validateExternalURL(_ url: URL) -> Bool {
        // Security: Whitelist of allowed URL schemes
        let allowedSchemes = ["http", "https", "mailto", "tel", "sms"]

        guard let scheme = url.scheme?.lowercased(),
              allowedSchemes.contains(scheme) else {
            print("Security: Blocked URL with disallowed scheme: \(url)")
            return false
        }

        // Security: Block suspicious patterns
        let urlString = url.absoluteString.lowercased()
        let blockedPatterns = [
            "javascript:",
            "data:",
            "file:",
            "vbscript:",
            "about:",
            "<script",
            "onclick",
            "onerror"
        ]

        for pattern in blockedPatterns {
            if urlString.contains(pattern) {
                print("Security: Blocked URL with suspicious pattern: \(pattern)")
                return false
            }
        }

        // Security: Validate URL can be opened
        guard UIApplication.shared.canOpenURL(url) else {
            return false
        }

        // Security: For HTTP/HTTPS, validate host exists
        if scheme == "http" || scheme == "https" {
            guard url.host != nil, !url.host!.isEmpty else {
                print("Security: Blocked URL with invalid host")
                return false
            }

            // Security: Block local network addresses for external links
            let blockedHosts = ["localhost", "127.0.0.1", "0.0.0.0", "::1"]
            if let host = url.host?.lowercased() {
                for blockedHost in blockedHosts {
                    if host.contains(blockedHost) {
                        print("Security: Blocked URL to local host: \(host)")
                        return false
                    }
                }
            }
        }

        return true
    }

    fileprivate func getEventTouchPoint(fromPositionParameterString positionParameterString: String) -> CGPoint? {
        // Remove the parameter names: "/clientX=188&clientY=292" -> "188&292"
        var positionParameterString = positionParameterString.replacingOccurrences(of: "/clientX=", with: "")
        positionParameterString = positionParameterString.replacingOccurrences(of: "clientY=", with: "")
        // Separate both position values into an array: "188&292" -> [188],[292]
        let positionStringValues = positionParameterString.components(separatedBy: "&")
        // Multiply the raw positions with the screen scale and return them as CGPoint
        if
            positionStringValues.count == 2,
            let xPos = Int(positionStringValues[0]),
            let yPos = Int(positionStringValues[1]) {
            return CGPoint(x: xPos, y: yPos)
        }
        return nil
    }

    // MARK: Gesture recognizer

    open func gestureRecognizer(_ gestureRecognizer: UIGestureRecognizer, shouldRecognizeSimultaneouslyWith otherGestureRecognizer: UIGestureRecognizer) -> Bool {
        if gestureRecognizer.view is FolioReaderWebView {
            if otherGestureRecognizer is UILongPressGestureRecognizer {
                if UIMenuController.shared.isMenuVisible {
                    webView?.setMenuVisible(false)
                }
                return false
            }
            return true
        }
        return false
    }

    @objc open func handleTapGesture(_ recognizer: UITapGestureRecognizer) {
        self.delegate?.pageTap?(recognizer)

        if let _navigationController = self.folioReader.readerCenter?.navigationController, (_navigationController.isNavigationBarHidden == true) {


            webView?.js("getSelectedText()") { selected in

                guard (selected == nil || selected?.isEmpty == true) else {
                    return
                }

                let delay = 0.4 * Double(NSEC_PER_SEC) // 0.4 seconds * nanoseconds per seconds
                let dispatchTime = (DispatchTime.now() + (Double(Int64(delay)) / Double(NSEC_PER_SEC)))

                DispatchQueue.main.asyncAfter(deadline: dispatchTime, execute: {
                    if (self.shouldShowBar == true && self.menuIsVisible == false) {
                        self.folioReader.readerCenter?.toggleBars()
                    }
                })
            }

        } else if (self.readerConfig.shouldHideNavigationOnTap == true) {
            self.folioReader.readerCenter?.hideBars()
            self.menuIsVisible = false
        }
    }

    // MARK: - Public scroll postion setter

    /**
     Scrolls the page to a given offset

     - parameter offset:   The offset to scroll
     - parameter animated: Enable or not scrolling animation
     */
    open func scrollPageToOffset(_ offset: CGFloat, animated: Bool) {
        let pageOffsetPoint = self.readerConfig.isDirection(CGPoint(x: 0, y: offset), CGPoint(x: offset, y: 0), CGPoint(x: 0, y: offset))
        webView?.scrollView.setContentOffset(pageOffsetPoint, animated: animated)
    }

    /**
     Scrolls the page to bottom
     */
    open func scrollPageToBottom() {
        guard let webView = webView else { return }
        let bottomOffset = self.readerConfig.isDirection(
            CGPoint(x: 0, y: webView.scrollView.contentSize.height - webView.scrollView.bounds.height),
            CGPoint(x: webView.scrollView.contentSize.width - webView.scrollView.bounds.width, y: 0),
            CGPoint(x: webView.scrollView.contentSize.width - webView.scrollView.bounds.width, y: 0)
        )

        if bottomOffset.forDirection(withConfiguration: self.readerConfig) >= 0 {
            DispatchQueue.main.async {
                self.webView?.scrollView.setContentOffset(bottomOffset, animated: false)
            }
        }
    }

    /**
     Handdle #anchors in html, get the offset and scroll to it

     - parameter anchor:                The #anchor
     - parameter avoidBeginningAnchors: Sometimes the anchor is on the beggining of the text, there is not need to scroll
     - parameter animated:              Enable or not scrolling animation
     */
    open func handleAnchor(_ anchor: String,  avoidBeginningAnchors: Bool, animated: Bool) {
        if !anchor.isEmpty {
            getAnchorOffset(anchor) { offset in

                switch self.readerConfig.scrollDirection {
                case .vertical, .defaultVertical:
                    let isBeginning = (offset < self.frame.forDirection(withConfiguration: self.readerConfig) * 0.5)

                    if !avoidBeginningAnchors {
                        self.scrollPageToOffset(offset, animated: animated)
                    } else if avoidBeginningAnchors && !isBeginning {
                        self.scrollPageToOffset(offset, animated: animated)
                    }
                case .horizontal, .horizontalWithVerticalContent:
                    self.scrollPageToOffset(offset, animated: animated)
                }

            }
        }
    }

    // MARK: Helper

    /**
     Get the #anchor offset in the page

     - parameter anchor: The #anchor id
     - returns: The element offset ready to scroll
     */
    func getAnchorOffset(_ anchor: String, completion: @escaping ((CGFloat) -> ())) {
        let horizontal = self.readerConfig.scrollDirection == .horizontal

        webView?.js("getAnchorOffset('\(anchor)', \(horizontal.description))") { strOffset in
            guard let strOffset = strOffset else {
                completion(CGFloat(0))
                return }
            completion(CGFloat((strOffset as NSString).floatValue))
        }

    }

    // MARK: Mark ID

    /**
     Audio Mark ID - marks an element with an ID with the given class and scrolls to it

     - parameter identifier: The identifier
     */
    func audioMarkID(_ identifier: String) {
        guard let currentPage = self.folioReader.readerCenter?.currentPage else {
            return
        }

        let playbackActiveClass = self.book.playbackActiveClass
        currentPage.webView?.js("audioMarkID('\(playbackActiveClass)','\(identifier)')") { _ in }
    }

    // MARK: UIMenu visibility

    override open func canPerformAction(_ action: Selector, withSender sender: Any?) -> Bool {
        guard let webView = webView else { return false }

        if UIMenuController.shared.menuItems?.count == 0 {
            webView.isColors = false
            webView.createMenu(options: false)
        }

        if !webView.isShare && !webView.isColors {

            webView.js("getSelectedText()") { result in

                guard let result = result, result.components(separatedBy: " ").count == 1 else {
                    webView.isOneWord = false
                    return
                }

                webView.isOneWord = true
                webView.createMenu(options: false)

            }
        }

        return super.canPerformAction(action, withSender: sender)
    }

    // MARK: ColorView fix for horizontal layout
    @objc func refreshPageMode() {
        guard let webView = webView else { return }

        if (self.folioReader.nightMode == true) {
            // omit create webView and colorView
            let script = "document.documentElement.offsetHeight"

            webView.js(script) { contentHeight in

                guard let contentHeight = Int(contentHeight ?? "") else {
                    self.colorView.frame = CGRect.zero
                    return
                }

                let frameHeight = webView.frame.height
//                let lastPageHeight = frameHeight * CGFloat(webView.pageCount) - CGFloat(Double(contentHeight!)!)
//                colorView.frame = CGRect(x: webView.frame.width * CGFloat(webView.pageCount-1), y: webView.frame.height - lastPageHeight, width: webView.frame.width, height: lastPageHeight)

            }

        }
    }


    // MARK: - Class based click listener

    fileprivate func setupClassBasedOnClickListeners() {
        for listener in self.readerConfig.classBasedOnClickListeners {
            self.webView?.js("addClassBasedOnClickListener(\"\(listener.schemeName)\", \"\(listener.querySelector)\", \"\(listener.attributeName)\", \"\(listener.selectAll)\")") { _ in }
        }
    }

}

//
//  FolioReaderWebView.swift
//  FolioReaderKit
//
//  Created by Hans Seiffert on 21.09.16.
//  Copyright (c) 2016 Folio Reader. All rights reserved.
//

import WebKit

public typealias JSCallback = ((String?) ->())

/// The custom WebView used in each page
open class FolioReaderWebView: WKWebView {

    var isColors = false
    var isShare = false
    var isOneWord = false

    fileprivate weak var readerContainer: FolioReaderContainer?

    fileprivate var readerConfig: FolioReaderConfig {
        guard let readerContainer = readerContainer else { return FolioReaderConfig() }
        return readerContainer.readerConfig
    }

    fileprivate var book: FRBook {
        guard let readerContainer = readerContainer else { return FRBook() }
        return readerContainer.book
    }

    fileprivate var folioReader: FolioReader {
        guard let readerContainer = readerContainer else { return FolioReader() }
        return readerContainer.folioReader
    }

    init(frame: CGRect, readerContainer: FolioReaderContainer) {
        self.readerContainer = readerContainer

        let configuration = WKWebViewConfiguration()
        if #available(iOS 10.0, *) {
            configuration.dataDetectorTypes = .link
        } else {
            // Fallback on earlier versions
            assertionFailure("unsupported iOS version")
        }
        super.init(frame: frame, configuration: configuration)
    }

    required public init?(coder aDecoder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    // MARK: - UIMenuController

    open override func canPerformAction(_ action: Selector, withSender sender: Any?) -> Bool {
        guard readerConfig.useReaderMenuController else {
            return super.canPerformAction(action, withSender: sender)
        }

        if isShare {
            return false
        } else if isColors {
            return false
        } else {
            if action == #selector(highlight(_:))
                || action == #selector(highlightWithNote(_:))
                || action == #selector(updateHighlightNote(_:))
                || (action == #selector(define(_:)) && isOneWord)
                || (action == #selector(play(_:)) && (book.hasAudio || readerConfig.enableTTS))
                || (action == #selector(share(_:)) && readerConfig.allowSharing)
                || (action == #selector(copy(_:)) && readerConfig.allowSharing) {
                return true
            }
            return false
        }
    }

    // MARK: - UIMenuController - Actions

    @objc func share(_ sender: UIMenuController) {
        let alertController = UIAlertController(title: nil, message: nil, preferredStyle: .actionSheet)

        let shareImage = UIAlertAction(title: self.readerConfig.localizedShareImageQuote, style: .default, handler: { (action) -> Void in
            if self.isShare {
                self.js("getHighlightContent()") { textToShare in
                    guard let textToShare = textToShare else { return }
                    self.folioReader.readerCenter?.presentQuoteShare(textToShare)
                }
            } else {
                self.js("getSelectedText()") { textToShare in
                    guard let textToShare = textToShare else { return }
                    self.folioReader.readerCenter?.presentQuoteShare(textToShare)

                    self.clearTextSelection()
                }
            }
            self.setMenuVisible(false)
        })

        // let shareText = UIAlertAction(title: self.readerConfig.localizedShareTextQuote, style: .default) { (action) -> Void in
        //     if self.isShare {
        //         self.js("getHighlightContent()") { textToShare in
        //             guard let textToShare = textToShare else { return }
        //             self.folioReader.readerCenter?.shareHighlight(textToShare, rect: sender.menuFrame)
        //         }
        //     } else {
        //         self.js("getSelectedText()") { textToShare in
        //             guard let textToShare = textToShare else { return }
        //             self.folioReader.readerCenter?.shareHighlight(textToShare, rect: sender.menuFrame)
        //         }
        //     }
        //     self.setMenuVisible(false)
        // }

        let cancel = UIAlertAction(title: self.readerConfig.localizedCancel, style: .cancel, handler: nil)

        alertController.addAction(shareImage)
        // alertController.addAction(shareText)
        alertController.addAction(cancel)

        if let alert = alertController.popoverPresentationController {
            alert.sourceView = self.folioReader.readerCenter?.currentPage
            alert.sourceRect = sender.menuFrame
        }

        self.folioReader.readerCenter?.present(alertController, animated: true, completion: nil)
    }

    func colors(_ sender: UIMenuController?) {
        isColors = true
        createMenu(options: false)
        setMenuVisible(true)
    }

    func remove(_ sender: UIMenuController?) {

        js("removeThisHighlight()") { removedId in
            guard let removedId = removedId else { return }
            Highlight.removeById(withConfiguration: self.readerConfig, highlightId: removedId)
        }

        setMenuVisible(false)
    }

    @objc func highlight(_ sender: UIMenuController?) {

        js("highlightString('\(HighlightStyle.classForStyle(self.folioReader.currentHighlightStyle))')") { highlightAndReturn in
            let jsonData = highlightAndReturn?.data(using: String.Encoding.utf8)

            do {
                let json = try JSONSerialization.jsonObject(with: jsonData!, options: []) as! NSArray
                let dic = json.firstObject as! [String: String]
                let rect = NSCoder.cgRect(for: dic["rect"]!)
                guard let startOffset = dic["startOffset"] else {
                    return
                }
                guard let endOffset = dic["endOffset"] else {
                    return
                }

                self.createMenu(options: true)
                self.setMenuVisible(true, andRect: rect)


                // Persist
                self.js("getHTML()") { html in

                    guard let html = html, let identifier = dic["id"], let bookId = (self.book.name as NSString?)?.deletingPathExtension
                        else {
                            return
                    }
                    let pageNumber = self.folioReader.readerCenter?.currentPageNumber ?? 0
                    let match = Highlight.MatchingHighlight(text: html, id: identifier, startOffset: startOffset, endOffset: endOffset, bookId: bookId, currentPage: pageNumber)
                    let highlight = Highlight.matchHighlight(match)
                    highlight?.persist(withConfiguration: self.readerConfig)
                }

            } catch {
                print("Could not receive JSON")
            }

        }

    }

    @objc func highlightWithNote(_ sender: UIMenuController?) {

        js("highlightStringWithNote('\(HighlightStyle.classForStyle(self.folioReader.currentHighlightStyle))')") { highlightAndReturn in

            guard let highlightAndReturn = highlightAndReturn,
                  let jsonData = highlightAndReturn.data(using: String.Encoding.utf8) else {
                print("Error: Could not get highlight data")
                return
            }

            do {
                guard let json = try JSONSerialization.jsonObject(with: jsonData, options: []) as? NSArray,
                      let dic = json.firstObject as? [String: String],
                      let startOffset = dic["startOffset"],
                      let endOffset = dic["endOffset"],
                      let identifier = dic["id"] else {
                    print("Error: Invalid highlight data format")
                    return
                }

                self.clearTextSelection()

                self.js("getHTML()") { html in

                    guard let html = html,
                          let bookId = (self.book.name as NSString?)?.deletingPathExtension else {
                        print("Error: Could not get HTML or book ID")
                        return
                    }

                    let pageNumber = self.folioReader.readerCenter?.currentPageNumber ?? 0
                    let match = Highlight.MatchingHighlight(text: html, id: identifier, startOffset: startOffset, endOffset: endOffset, bookId: bookId, currentPage: pageNumber)

                    if let highlight = Highlight.matchHighlight(match) {
                        DispatchQueue.main.async {
                            self.folioReader.readerCenter?.presentAddHighlightNote(highlight, edit: false)
                        }
                    } else {
                        print("Error: Could not match highlight")
                    }
                }
            } catch {
                print("Could not parse JSON: \(error)")
            }
        }
    }

    @objc func updateHighlightNote (_ sender: UIMenuController?) {

        js("getHighlightId()") { highlightId in
            guard let highlightId = highlightId, let highlightNote = Highlight.getById(withConfiguration: self.readerConfig, highlightId: highlightId) else { return }
            self.folioReader.readerCenter?.presentAddHighlightNote(highlightNote, edit: true)
        }

    }

    @objc func define(_ sender: UIMenuController?) {

        js("getSelectedText()") { selectedText in

            guard let selectedText = selectedText else { return }

            self.setMenuVisible(false)
            self.clearTextSelection()

            let vc = UIReferenceLibraryViewController(term: selectedText)
            vc.view.tintColor = self.readerConfig.tintColor
            guard let readerContainer = self.readerContainer else { return }
            readerContainer.show(vc, sender: nil)

        }

    }

    @objc func play(_ sender: UIMenuController?) {
        self.folioReader.readerAudioPlayer?.play()

        self.clearTextSelection()
    }

    func setYellow(_ sender: UIMenuController?) {
        changeHighlightStyle(sender, style: .yellow)
    }

    func setGreen(_ sender: UIMenuController?) {
        changeHighlightStyle(sender, style: .green)
    }

    func setBlue(_ sender: UIMenuController?) {
        changeHighlightStyle(sender, style: .blue)
    }

    func setPink(_ sender: UIMenuController?) {
        changeHighlightStyle(sender, style: .pink)
    }

    func setUnderline(_ sender: UIMenuController?) {
        changeHighlightStyle(sender, style: .underline)
    }

    func changeHighlightStyle(_ sender: UIMenuController?, style: HighlightStyle) {
        self.folioReader.currentHighlightStyle = style.rawValue

        js("setHighlightStyle('\(HighlightStyle.classForStyle(style.rawValue))')") { updateId in
            guard let updateId = updateId else { return }
            Highlight.updateById(withConfiguration: self.readerConfig, highlightId: updateId, type: style)
        }

        //FIX: https://github.com/FolioReader/FolioReaderKit/issues/316
        setMenuVisible(false)
    }

    // MARK: - Create and show menu

    func createMenu(options: Bool) {
        guard (self.readerConfig.useReaderMenuController == true) else {
            return
        }

        isShare = options

        let colors = UIImage(readerImageNamed: "colors-marker")
        let share = UIImage(readerImageNamed: "share-marker")
        let remove = UIImage(readerImageNamed: "no-marker")
        let yellow = UIImage(readerImageNamed: "yellow-marker")
        let green = UIImage(readerImageNamed: "green-marker")
        let blue = UIImage(readerImageNamed: "blue-marker")
        let pink = UIImage(readerImageNamed: "pink-marker")
        let underline = UIImage(readerImageNamed: "underline-marker")

        let menuController = UIMenuController.shared

        let highlightItem = UIMenuItem(title: self.readerConfig.localizedHighlightMenu, action: #selector(highlight(_:)))
        let highlightNoteItem = UIMenuItem(title: self.readerConfig.localizedHighlightNote, action: #selector(highlightWithNote(_:)))
        let editNoteItem = UIMenuItem(title: self.readerConfig.localizedHighlightNote, action: #selector(updateHighlightNote(_:)))
        let playAudioItem = UIMenuItem(title: self.readerConfig.localizedPlayMenu, action: #selector(play(_:)))
        let defineItem = UIMenuItem(title: self.readerConfig.localizedDefineMenu, action: #selector(define(_:)))
        let colorsItem = UIMenuItem(title: "C", image: colors) { [weak self] _ in
            self?.colors(menuController)
        }
        let shareItem = UIMenuItem(title: "S", image: share) { [weak self] _ in
            self?.share(menuController)
        }
        let removeItem = UIMenuItem(title: "R", image: remove) { [weak self] _ in
            self?.remove(menuController)
        }
        let yellowItem = UIMenuItem(title: "Y", image: yellow) { [weak self] _ in
            self?.setYellow(menuController)
        }
        let greenItem = UIMenuItem(title: "G", image: green) { [weak self] _ in
            self?.setGreen(menuController)
        }
        let blueItem = UIMenuItem(title: "B", image: blue) { [weak self] _ in
            self?.setBlue(menuController)
        }
        let pinkItem = UIMenuItem(title: "P", image: pink) { [weak self] _ in
            self?.setPink(menuController)
        }
        let underlineItem = UIMenuItem(title: "U", image: underline) { [weak self] _ in
            self?.setUnderline(menuController)
        }

        var menuItems: [UIMenuItem] = []

        // menu on existing highlight
        if isShare {
            menuItems = [colorsItem, editNoteItem, removeItem]

            if (self.readerConfig.allowSharing == true) {
                menuItems.append(shareItem)
            }

            isShare = false
        } else if isColors {
            // menu for selecting highlight color
            menuItems = [yellowItem, greenItem, blueItem, pinkItem, underlineItem]
        } else {
            // default menu
            menuItems = [highlightItem, defineItem, highlightNoteItem]

            if self.book.hasAudio || self.readerConfig.enableTTS {
                menuItems.insert(playAudioItem, at: 0)
            }

            if (self.readerConfig.allowSharing == true) {
                menuItems.append(shareItem)
            }
        }

        menuController.menuItems = menuItems
    }

    open func setMenuVisible(_ menuVisible: Bool, animated: Bool = true, andRect rect: CGRect = CGRect.zero) {
        if !menuVisible && isShare || !menuVisible && isColors {
            isColors = false
            isShare = false
        }

        if menuVisible  {
            if !rect.equalTo(CGRect.zero) {
                UIMenuController.shared.setTargetRect(rect, in: self)
            }
        }

        UIMenuController.shared.setMenuVisible(menuVisible, animated: animated)
    }

    // MARK: - Java Script Bridge

    open func js(_ script: String, completion: @escaping JSCallback) {

        self.evaluateJavaScript(script) { (result, error) in
            completion(result as? String)
        }

    }

    // MARK: WebView

    func clearTextSelection() {
        // Forces text selection clearing
        // @NOTE: this doesn't seem to always work

        self.isUserInteractionEnabled = false
        self.isUserInteractionEnabled = true
    }

    /// Sets up the scroll direction and paging behavior for the web view
    @objc open func setupScrollDirection() {
        switch self.readerConfig.scrollDirection {
        case .vertical, .defaultVertical:
            // Traditional vertical scrolling - no paging, continuous scroll
            scrollView.isPagingEnabled = false
            scrollView.bounces = true
            scrollView.alwaysBounceVertical = true
            scrollView.alwaysBounceHorizontal = false
            scrollView.showsVerticalScrollIndicator = true
            scrollView.showsHorizontalScrollIndicator = false

            // Apply vertical CSS class and remove any column styling
            self.evaluateJavaScript("""
                // Add vertical class for CSS styling
                document.documentElement.className = document.documentElement.className.replace(/\\b(horizontal|horizontalWithVerticalContent)\\b/g, '').trim();
                document.documentElement.classList.add('vertical');
                document.body.className = document.body.className.replace(/\\b(horizontal|horizontalWithVerticalContent)\\b/g, '').trim();
                document.body.classList.add('vertical');

                // Remove any column layout
                document.documentElement.style.webkitColumnCount = 'auto';
                document.documentElement.style.webkitColumnWidth = 'auto';
                document.documentElement.style.webkitColumnGap = '0px';
                document.body.style.webkitColumnCount = 'auto';
                document.body.style.webkitColumnWidth = 'auto';
                document.body.style.webkitColumnGap = '0px';

                // Ensure full width and natural height
                document.documentElement.style.width = '100%';
                document.documentElement.style.height = 'auto';
                document.body.style.width = '100%';
                document.body.style.maxWidth = '100%';
                document.body.style.height = 'auto';
                document.body.style.margin = '0';
                document.body.style.padding = '40px 20px';
                document.body.style.boxSizing = 'border-box';
            """, completionHandler: nil)
            break

        case .horizontal:
            // Traditional horizontal paging - content flows in columns
            scrollView.isPagingEnabled = true
            scrollView.bounces = false
            scrollView.alwaysBounceVertical = false
            scrollView.alwaysBounceHorizontal = true
            scrollView.showsVerticalScrollIndicator = false
            scrollView.showsHorizontalScrollIndicator = false

            let pageWidth = Int(self.frame.width - 80) // Account for padding
            let columnGap = 40

            self.evaluateJavaScript("""
                // Add horizontal class for CSS styling
                document.documentElement.className = document.documentElement.className.replace(/\\b(vertical|horizontalWithVerticalContent)\\b/g, '').trim();
                document.documentElement.classList.add('horizontal');
                document.body.className = document.body.className.replace(/\\b(vertical|horizontalWithVerticalContent)\\b/g, '').trim();
                document.body.classList.add('horizontal');

                // Set up column layout
                document.documentElement.style.webkitColumnWidth = '\(pageWidth)px';
                document.documentElement.style.webkitColumnGap = '\(columnGap)px';
                document.documentElement.style.webkitColumnFill = 'auto';
                document.body.style.webkitColumnWidth = '\(pageWidth)px';
                document.body.style.webkitColumnGap = '\(columnGap)px';
                document.body.style.webkitColumnFill = 'auto';

                document.body.style.margin = '0';
                document.body.style.padding = '40px 20px';
            """, completionHandler: nil)
            break

        case .horizontalWithVerticalContent:
            // Hybrid mode - vertical scrolling content within horizontal page navigation
            scrollView.isPagingEnabled = false
            scrollView.bounces = true
            scrollView.alwaysBounceVertical = true
            scrollView.alwaysBounceHorizontal = false
            scrollView.showsVerticalScrollIndicator = true
            scrollView.showsHorizontalScrollIndicator = false

            self.evaluateJavaScript("""
                // Add horizontalWithVerticalContent class for CSS styling
                document.documentElement.className = document.documentElement.className.replace(/\\b(vertical|horizontal)\\b/g, '').trim();
                document.documentElement.classList.add('horizontalWithVerticalContent');
                document.body.className = document.body.className.replace(/\\b(vertical|horizontal)\\b/g, '').trim();
                document.body.classList.add('horizontalWithVerticalContent');

                // Remove any column layout for vertical flow
                document.documentElement.style.webkitColumnCount = 'auto';
                document.documentElement.style.webkitColumnWidth = 'auto';
                document.documentElement.style.webkitColumnGap = '0px';
                document.body.style.webkitColumnCount = 'auto';
                document.body.style.webkitColumnWidth = 'auto';
                document.body.style.webkitColumnGap = '0px';

                // Set up full-width vertical content flow
                document.documentElement.style.width = '100%';
                document.documentElement.style.height = 'auto';
                document.body.style.width = '100%';
                document.body.style.maxWidth = '100%';
                document.body.style.height = 'auto';
                document.body.style.margin = '0';
                document.body.style.padding = '40px 20px';
                document.body.style.boxSizing = 'border-box';

                // Ensure proper text wrapping
                document.body.style.wordWrap = 'break-word';
                document.body.style.overflowWrap = 'break-word';
            """, completionHandler: nil)
            break
        }
    }
}

//
//  FolioReaderWebView.swift
//  FolioReaderKit
//
//  Created by Hans Seiffert on 21.09.16.
//  Copyright (c) 2016 Folio Reader. All rights reserved.
//

import WebKit

public typealias JSCallback = ((String?) ->())

/// The custom WebView used in each page
open class FolioReaderWebView: WKWebView {

    var isColors = false
    var isShare = false
    var isOneWord = false

    fileprivate weak var readerContainer: FolioReaderContainer?

    fileprivate var readerConfig: FolioReaderConfig {
        guard let readerContainer = readerContainer else { return FolioReaderConfig() }
        return readerContainer.readerConfig
    }

    fileprivate var book: FRBook {
        guard let readerContainer = readerContainer else { return FRBook() }
        return readerContainer.book
    }

    fileprivate var folioReader: FolioReader {
        guard let readerContainer = readerContainer else { return FolioReader() }
        return readerContainer.folioReader
    }

    init(frame: CGRect, readerContainer: FolioReaderContainer) {
        self.readerContainer = readerContainer

        let configuration = WKWebViewConfiguration()

        // Security: Configure data detectors
        if #available(iOS 10.0, *) {
            configuration.dataDetectorTypes = .link
        } else {
            // Fallback on earlier versions
            assertionFailure("unsupported iOS version")
        }

        // Security: Restrict media playback - require user action for all media
        if #available(iOS 10.0, *) {
            configuration.mediaTypesRequiringUserActionForPlayback = .all
        } else {
            configuration.requiresUserActionForMediaPlayback = true
        }

        // Security: Control inline media playback
        configuration.allowsInlineMediaPlayback = false

        // Security: Disable picture-in-picture for better control
        if #available(iOS 9.0, *) {
            configuration.allowsPictureInPictureMediaPlayback = false
        }

        // Security: Configure preferences
        let preferences = WKPreferences()
        // Note: JavaScript is required for EPUB functionality
        // Additional JS validation is handled in the js() method
        preferences.javaScriptEnabled = true
        preferences.javaScriptCanOpenWindowsAutomatically = false
        configuration.preferences = preferences

        // Security: Disable web page preview
        if #available(iOS 13.0, *) {
            configuration.defaultWebpagePreferences.preferredContentMode = .mobile
        }

        // Real Device Fix: Enable local file access for EPUB resources
        // This is critical for loading images and resources on real devices
        if #available(iOS 9.0, *) {
            configuration.preferences.setValue(true, forKey: "allowFileAccessFromFileURLs")
        }

        super.init(frame: frame, configuration: configuration)

        // Real Device Fix: Additional configuration for local resource loading
        if #available(iOS 11.0, *) {
            // Allow access to local files (needed for EPUB content on real devices)
            self.configuration.preferences.setValue(true, forKey: "allowUniversalAccessFromFileURLs")
        }
    }

    required public init?(coder aDecoder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    // MARK: - UIMenuController

    open override func canPerformAction(_ action: Selector, withSender sender: Any?) -> Bool {
        guard readerConfig.useReaderMenuController else {
            return super.canPerformAction(action, withSender: sender)
        }

        if isShare {
            return false
        } else if isColors {
            return false
        } else {
            if action == #selector(highlight(_:))
                || action == #selector(highlightWithNote(_:))
                || action == #selector(updateHighlightNote(_:))
                || (action == #selector(define(_:)) && isOneWord)
                || (action == #selector(play(_:)) && (book.hasAudio || readerConfig.enableTTS))
                || (action == #selector(share(_:)) && readerConfig.allowSharing)
                || (action == #selector(copy(_:)) && readerConfig.allowSharing) {
                return true
            }
            return false
        }
    }

    // MARK: - UIMenuController - Actions

    @objc func share(_ sender: UIMenuController) {
        let alertController = UIAlertController(title: nil, message: nil, preferredStyle: .actionSheet)

        let shareImage = UIAlertAction(title: self.readerConfig.localizedShareImageQuote, style: .default, handler: { (action) -> Void in
            if self.isShare {
                self.js("getHighlightContent()") { textToShare in
                    guard let textToShare = textToShare else { return }
                    self.folioReader.readerCenter?.presentQuoteShare(textToShare)
                }
            } else {
                self.js("getSelectedText()") { textToShare in
                    guard let textToShare = textToShare else { return }
                    self.folioReader.readerCenter?.presentQuoteShare(textToShare)

                    self.clearTextSelection()
                }
            }
            self.setMenuVisible(false)
        })

        // let shareText = UIAlertAction(title: self.readerConfig.localizedShareTextQuote, style: .default) { (action) -> Void in
        //     if self.isShare {
        //         self.js("getHighlightContent()") { textToShare in
        //             guard let textToShare = textToShare else { return }
        //             self.folioReader.readerCenter?.shareHighlight(textToShare, rect: sender.menuFrame)
        //         }
        //     } else {
        //         self.js("getSelectedText()") { textToShare in
        //             guard let textToShare = textToShare else { return }
        //             self.folioReader.readerCenter?.shareHighlight(textToShare, rect: sender.menuFrame)
        //         }
        //     }
        //     self.setMenuVisible(false)
        // }

        let cancel = UIAlertAction(title: self.readerConfig.localizedCancel, style: .cancel, handler: nil)

        alertController.addAction(shareImage)
        // alertController.addAction(shareText)
        alertController.addAction(cancel)

        if let alert = alertController.popoverPresentationController {
            alert.sourceView = self.folioReader.readerCenter?.currentPage
            alert.sourceRect = sender.menuFrame
        }

        self.folioReader.readerCenter?.present(alertController, animated: true, completion: nil)
    }

    func colors(_ sender: UIMenuController?) {
        isColors = true
        createMenu(options: false)
        setMenuVisible(true)
    }

    func remove(_ sender: UIMenuController?) {

        js("removeThisHighlight()") { removedId in
            guard let removedId = removedId else { return }
            Highlight.removeById(withConfiguration: self.readerConfig, highlightId: removedId)
        }

        setMenuVisible(false)
    }

    @objc func highlight(_ sender: UIMenuController?) {

        js("highlightString('\(HighlightStyle.classForStyle(self.folioReader.currentHighlightStyle))')") { highlightAndReturn in
            let jsonData = highlightAndReturn?.data(using: String.Encoding.utf8)

            do {
                let json = try JSONSerialization.jsonObject(with: jsonData!, options: []) as! NSArray
                let dic = json.firstObject as! [String: String]
                let rect = NSCoder.cgRect(for: dic["rect"]!)
                guard let startOffset = dic["startOffset"] else {
                    return
                }
                guard let endOffset = dic["endOffset"] else {
                    return
                }

                self.createMenu(options: true)
                self.setMenuVisible(true, andRect: rect)


                // Persist
                self.js("getHTML()") { html in

                    guard let html = html, let identifier = dic["id"], let bookId = (self.book.name as NSString?)?.deletingPathExtension
                        else {
                            return
                    }
                    let pageNumber = self.folioReader.readerCenter?.currentPageNumber ?? 0
                    let match = Highlight.MatchingHighlight(text: html, id: identifier, startOffset: startOffset, endOffset: endOffset, bookId: bookId, currentPage: pageNumber)
                    let highlight = Highlight.matchHighlight(match)
                    highlight?.persist(withConfiguration: self.readerConfig)
                }

            } catch {
                print("Could not receive JSON")
            }

        }

    }

    @objc func highlightWithNote(_ sender: UIMenuController?) {

        js("highlightStringWithNote('\(HighlightStyle.classForStyle(self.folioReader.currentHighlightStyle))')") { highlightAndReturn in

            guard let highlightAndReturn = highlightAndReturn,
                  let jsonData = highlightAndReturn.data(using: String.Encoding.utf8) else {
                print("Error: Could not get highlight data")
                return
            }

            do {
                guard let json = try JSONSerialization.jsonObject(with: jsonData, options: []) as? NSArray,
                      let dic = json.firstObject as? [String: String],
                      let startOffset = dic["startOffset"],
                      let endOffset = dic["endOffset"],
                      let identifier = dic["id"] else {
                    print("Error: Invalid highlight data format")
                    return
                }

                self.clearTextSelection()

                self.js("getHTML()") { html in

                    guard let html = html,
                          let bookId = (self.book.name as NSString?)?.deletingPathExtension else {
                        print("Error: Could not get HTML or book ID")
                        return
                    }

                    let pageNumber = self.folioReader.readerCenter?.currentPageNumber ?? 0
                    let match = Highlight.MatchingHighlight(text: html, id: identifier, startOffset: startOffset, endOffset: endOffset, bookId: bookId, currentPage: pageNumber)

                    if let highlight = Highlight.matchHighlight(match) {
                        DispatchQueue.main.async {
                            self.folioReader.readerCenter?.presentAddHighlightNote(highlight, edit: false)
                        }
                    } else {
                        print("Error: Could not match highlight")
                    }
                }
            } catch {
                print("Could not parse JSON: \(error)")
            }
        }
    }

    @objc func updateHighlightNote (_ sender: UIMenuController?) {

        js("getHighlightId()") { highlightId in
            guard let highlightId = highlightId, let highlightNote = Highlight.getById(withConfiguration: self.readerConfig, highlightId: highlightId) else { return }
            self.folioReader.readerCenter?.presentAddHighlightNote(highlightNote, edit: true)
        }

    }

    @objc func define(_ sender: UIMenuController?) {

        js("getSelectedText()") { selectedText in

            guard let selectedText = selectedText else { return }

            self.setMenuVisible(false)
            self.clearTextSelection()

            let vc = UIReferenceLibraryViewController(term: selectedText)
            vc.view.tintColor = self.readerConfig.tintColor
            guard let readerContainer = self.readerContainer else { return }
            readerContainer.show(vc, sender: nil)

        }

    }

    @objc func play(_ sender: UIMenuController?) {
        self.folioReader.readerAudioPlayer?.play()

        self.clearTextSelection()
    }

    func setYellow(_ sender: UIMenuController?) {
        changeHighlightStyle(sender, style: .yellow)
    }

    func setGreen(_ sender: UIMenuController?) {
        changeHighlightStyle(sender, style: .green)
    }

    func setBlue(_ sender: UIMenuController?) {
        changeHighlightStyle(sender, style: .blue)
    }

    func setPink(_ sender: UIMenuController?) {
        changeHighlightStyle(sender, style: .pink)
    }

    func setUnderline(_ sender: UIMenuController?) {
        changeHighlightStyle(sender, style: .underline)
    }

    func changeHighlightStyle(_ sender: UIMenuController?, style: HighlightStyle) {
        self.folioReader.currentHighlightStyle = style.rawValue

        js("setHighlightStyle('\(HighlightStyle.classForStyle(style.rawValue))')") { updateId in
            guard let updateId = updateId else { return }
            Highlight.updateById(withConfiguration: self.readerConfig, highlightId: updateId, type: style)
        }

        //FIX: https://github.com/FolioReader/FolioReaderKit/issues/316
        setMenuVisible(false)
    }

    // MARK: - Create and show menu

    func createMenu(options: Bool) {
        guard (self.readerConfig.useReaderMenuController == true) else {
            return
        }

        isShare = options

        let colors = UIImage(readerImageNamed: "colors-marker")
        let share = UIImage(readerImageNamed: "share-marker")
        let remove = UIImage(readerImageNamed: "no-marker")
        let yellow = UIImage(readerImageNamed: "yellow-marker")
        let green = UIImage(readerImageNamed: "green-marker")
        let blue = UIImage(readerImageNamed: "blue-marker")
        let pink = UIImage(readerImageNamed: "pink-marker")
        let underline = UIImage(readerImageNamed: "underline-marker")

        let menuController = UIMenuController.shared

        let highlightItem = UIMenuItem(title: self.readerConfig.localizedHighlightMenu, action: #selector(highlight(_:)))
        let highlightNoteItem = UIMenuItem(title: self.readerConfig.localizedHighlightNote, action: #selector(highlightWithNote(_:)))
        let editNoteItem = UIMenuItem(title: self.readerConfig.localizedHighlightNote, action: #selector(updateHighlightNote(_:)))
        let playAudioItem = UIMenuItem(title: self.readerConfig.localizedPlayMenu, action: #selector(play(_:)))
        let defineItem = UIMenuItem(title: self.readerConfig.localizedDefineMenu, action: #selector(define(_:)))
        let colorsItem = UIMenuItem(title: "C", image: colors) { [weak self] _ in
            self?.colors(menuController)
        }
        let shareItem = UIMenuItem(title: "S", image: share) { [weak self] _ in
            self?.share(menuController)
        }
        let removeItem = UIMenuItem(title: "R", image: remove) { [weak self] _ in
            self?.remove(menuController)
        }
        let yellowItem = UIMenuItem(title: "Y", image: yellow) { [weak self] _ in
            self?.setYellow(menuController)
        }
        let greenItem = UIMenuItem(title: "G", image: green) { [weak self] _ in
            self?.setGreen(menuController)
        }
        let blueItem = UIMenuItem(title: "B", image: blue) { [weak self] _ in
            self?.setBlue(menuController)
        }
        let pinkItem = UIMenuItem(title: "P", image: pink) { [weak self] _ in
            self?.setPink(menuController)
        }
        let underlineItem = UIMenuItem(title: "U", image: underline) { [weak self] _ in
            self?.setUnderline(menuController)
        }

        var menuItems: [UIMenuItem] = []

        // menu on existing highlight
        if isShare {
            menuItems = [colorsItem, editNoteItem, removeItem]

            if (self.readerConfig.allowSharing == true) {
                menuItems.append(shareItem)
            }

            isShare = false
        } else if isColors {
            // menu for selecting highlight color
            menuItems = [yellowItem, greenItem, blueItem, pinkItem, underlineItem]
        } else {
            // default menu
            menuItems = [highlightItem, defineItem, highlightNoteItem]

            if self.book.hasAudio || self.readerConfig.enableTTS {
                menuItems.insert(playAudioItem, at: 0)
            }

            if (self.readerConfig.allowSharing == true) {
                menuItems.append(shareItem)
            }
        }

        menuController.menuItems = menuItems
    }

    open func setMenuVisible(_ menuVisible: Bool, animated: Bool = true, andRect rect: CGRect = CGRect.zero) {
        if !menuVisible && isShare || !menuVisible && isColors {
            isColors = false
            isShare = false
        }

        if menuVisible  {
            if !rect.equalTo(CGRect.zero) {
                UIMenuController.shared.setTargetRect(rect, in: self)
            }
        }

        UIMenuController.shared.setMenuVisible(menuVisible, animated: animated)
    }

    // MARK: - Java Script Bridge

    open func js(_ script: String, completion: @escaping JSCallback) {
        // Security: Validate JavaScript before execution
        guard validateJavaScript(script) else {
            print("Security: Blocked potentially unsafe JavaScript execution")
            completion(nil)
            return
        }

        self.evaluateJavaScript(script) { (result, error) in
            if let error = error {
                print("JavaScript execution error: \(error.localizedDescription)")
                completion(nil)
            } else {
                completion(result as? String)
            }
        }
    }

    // MARK: - Security Methods (Section 3)

    /// Validates JavaScript code before execution
    private func validateJavaScript(_ script: String) -> Bool {
        // Security: Check for empty or whitespace-only scripts
        guard !script.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return false
        }

        // Security: Length limit to prevent excessively large scripts
        let maxScriptLength = 50000 // 50KB
        guard script.count <= maxScriptLength else {
            print("Security: JavaScript exceeds maximum length")
            return false
        }

        // Security: Whitelist of allowed function prefixes
        let allowedPrefixes = [
            "document.",
            "window.getSelection",
            "highlightString",
            "highlightStringWithNote",
            "removeThisHighlight",
            "removeHighlightById",
            "setHighlightStyle",
            "getHighlightContent",
            "getSelectedText",
            "getHTML",
            "nightMode",
            "setFontName",
            "setFontSize",
            "getReadingTime",
            "wrappingSentencesWithinPTags",
            "setMediaOverlayStyleColors",
            "addClassBasedOnClickListener",
            "playAudio",
            "pauseAudio",
            "addClass",
            "removeClass"
        ]

        // Check if script starts with an allowed prefix or is a simple property access
        let trimmedScript = script.trimmingCharacters(in: .whitespacesAndNewlines)
        let isAllowed = allowedPrefixes.contains { prefix in
            trimmedScript.hasPrefix(prefix)
        }

        if !isAllowed {
            print("Security: JavaScript function not in whitelist: \(String(trimmedScript.prefix(50)))")
        }

        // Security: Block dangerous JavaScript patterns
        let dangerousPatterns = [
            "eval(",
            "Function(",
            "setTimeout(",
            "setInterval(",
            "XMLHttpRequest",
            "fetch(",
            ".innerHTML =",
            "document.write",
            "document.cookie",
            "localStorage.",
            "sessionStorage.",
            "indexedDB",
            "<script",
            "javascript:",
            "data:",
            "vbscript:",
            "file:",
            "chrome:",
            "webkit:"
        ]

        let lowerScript = script.lowercased()
        for pattern in dangerousPatterns {
            if lowerScript.contains(pattern.lowercased()) {
                print("Security: Blocked JavaScript with dangerous pattern: \(pattern)")
                return false
            }
        }

        return isAllowed
    }

    // MARK: WebView

    func clearTextSelection() {
        // Forces text selection clearing
        // @NOTE: this doesn't seem to always work

        self.isUserInteractionEnabled = false
        self.isUserInteractionEnabled = true
    }

    /// Sets up the scroll direction and paging behavior for the web view
    @objc open func setupScrollDirection() {
        switch self.readerConfig.scrollDirection {
        case .vertical, .defaultVertical:
            // Traditional vertical scrolling - no paging, continuous scroll
            scrollView.isPagingEnabled = false
            scrollView.bounces = true
            scrollView.alwaysBounceVertical = true
            scrollView.alwaysBounceHorizontal = false
            scrollView.showsVerticalScrollIndicator = true
            scrollView.showsHorizontalScrollIndicator = false

            // Apply vertical CSS class and remove any column styling
            self.evaluateJavaScript("""
                // Add vertical class for CSS styling
                document.documentElement.className = document.documentElement.className.replace(/\\b(horizontal|horizontalWithVerticalContent)\\b/g, '').trim();
                document.documentElement.classList.add('vertical');
                document.body.className = document.body.className.replace(/\\b(horizontal|horizontalWithVerticalContent)\\b/g, '').trim();
                document.body.classList.add('vertical');

                // Remove any column layout
                document.documentElement.style.webkitColumnCount = 'auto';
                document.documentElement.style.webkitColumnWidth = 'auto';
                document.documentElement.style.webkitColumnGap = '0px';
                document.body.style.webkitColumnCount = 'auto';
                document.body.style.webkitColumnWidth = 'auto';
                document.body.style.webkitColumnGap = '0px';

                // Ensure full width and natural height
                document.documentElement.style.width = '100%';
                document.documentElement.style.height = 'auto';
                document.body.style.width = '100%';
                document.body.style.maxWidth = '100%';
                document.body.style.height = 'auto';
                document.body.style.margin = '0';
                document.body.style.padding = '40px 20px';
                document.body.style.boxSizing = 'border-box';
            """, completionHandler: nil)
            break

        case .horizontal:
            // Traditional horizontal paging - content flows in columns
            scrollView.isPagingEnabled = true
            scrollView.bounces = false
            scrollView.alwaysBounceVertical = false
            scrollView.alwaysBounceHorizontal = true
            scrollView.showsVerticalScrollIndicator = false
            scrollView.showsHorizontalScrollIndicator = false

            let pageWidth = Int(self.frame.width - 80) // Account for padding
            let columnGap = 40

            self.evaluateJavaScript("""
                // Add horizontal class for CSS styling
                document.documentElement.className = document.documentElement.className.replace(/\\b(vertical|horizontalWithVerticalContent)\\b/g, '').trim();
                document.documentElement.classList.add('horizontal');
                document.body.className = document.body.className.replace(/\\b(vertical|horizontalWithVerticalContent)\\b/g, '').trim();
                document.body.classList.add('horizontal');

                // Set up column layout
                document.documentElement.style.webkitColumnWidth = '\(pageWidth)px';
                document.documentElement.style.webkitColumnGap = '\(columnGap)px';
                document.documentElement.style.webkitColumnFill = 'auto';
                document.body.style.webkitColumnWidth = '\(pageWidth)px';
                document.body.style.webkitColumnGap = '\(columnGap)px';
                document.body.style.webkitColumnFill = 'auto';

                document.body.style.margin = '0';
                document.body.style.padding = '40px 20px';
            """, completionHandler: nil)
            break

        case .horizontalWithVerticalContent:
            // Hybrid mode - vertical scrolling content within horizontal page navigation
            scrollView.isPagingEnabled = false
            scrollView.bounces = true
            scrollView.alwaysBounceVertical = true
            scrollView.alwaysBounceHorizontal = false
            scrollView.showsVerticalScrollIndicator = true
            scrollView.showsHorizontalScrollIndicator = false

            self.evaluateJavaScript("""
                // Add horizontalWithVerticalContent class for CSS styling
                document.documentElement.className = document.documentElement.className.replace(/\\b(vertical|horizontal)\\b/g, '').trim();
                document.documentElement.classList.add('horizontalWithVerticalContent');
                document.body.className = document.body.className.replace(/\\b(vertical|horizontal)\\b/g, '').trim();
                document.body.classList.add('horizontalWithVerticalContent');

                // Remove any column layout for vertical flow
                document.documentElement.style.webkitColumnCount = 'auto';
                document.documentElement.style.webkitColumnWidth = 'auto';
                document.documentElement.style.webkitColumnGap = '0px';
                document.body.style.webkitColumnCount = 'auto';
                document.body.style.webkitColumnWidth = 'auto';
                document.body.style.webkitColumnGap = '0px';

                // Set up full-width vertical content flow
                document.documentElement.style.width = '100%';
                document.documentElement.style.height = 'auto';
                document.body.style.width = '100%';
                document.body.style.maxWidth = '100%';
                document.body.style.height = 'auto';
                document.body.style.margin = '0';
                document.body.style.padding = '40px 20px';
                document.body.style.boxSizing = 'border-box';

                // Ensure proper text wrapping
                document.body.style.wordWrap = 'break-word';
                document.body.style.overflowWrap = 'break-word';
            """, completionHandler: nil)
            break
        }
    }
}
